package dev.gbppimentel.zzz;
public final class FrameRateTest {
 static String frames(long start,long step,int n){StringBuilder b=new StringBuilder("16666666\n0 0 0\n1 9223372036854775807 3\n");for(int i=0;i<n;i++)b.append("0 ").append(start+i*step).append(" 0\n");return b.toString();}
 public static void main(String[] args){long now=100000000000L;int n=0;FrameRate.Sample sixty=FrameRate.parse(frames(now-2000000000L,16666667,120),now);if(sixty.fps==null||Math.abs(sixty.fps-60)>.2)throw new AssertionError("60 FPS");n++;FrameRate.Sample thirty=FrameRate.parse(frames(now-2000000000L,33333333,60),now);if(thirty.fps==null||Math.abs(thirty.fps-30)>.2)throw new AssertionError("30 FPS must not become 60 Hz");n++;if(FrameRate.parse("16666666\n0 0 0\n",now).fps!=null)throw new AssertionError("Refresh period is not FPS");n++;if(FrameRate.parse(frames(now-10000000000L,16666667,120),now).fps!=null)throw new AssertionError("Stale samples cannot stay live");n++;if(FrameRate.parse(frames(now+1000000000L,16666667,120),now).fps!=null)throw new AssertionError("Future timestamps");n++;String x=frames(now-1000000000L,16666667,60);if(FrameRate.parse(x+x,now).fps>61)throw new AssertionError("Duplicate presented frames");n++;String layers="Background for SurfaceView[com.HoYoverse.Nap/game](BLAST)#1\nSurfaceView[com.other/game](BLAST)#2\nSurfaceView[com.HoYoverse.Nap/game]#3\nSurfaceView[com.HoYoverse.Nap/game](BLAST)#4\n";if(FrameRate.layers(layers).size()!=1||!FrameRate.layers(layers).get(0).endsWith("#4"))throw new AssertionError("Only the actual ZZZ buffer layer");n++;System.out.println(n+" frame-rate checks passed");}
}
